const weekOf = $now.setZone('Asia/Kolkata').minus({ days: 6 }).toFormat('d LLL');
const advisors = {};
for (const { json: r } of $input.all()) {
  (advisors[r.advisor_id] ??= { name: r.advisor_name, clickup_user_id: r.clickup_user_id, rows: [] }).rows.push(r);
}
const top3 = list => list.sort((a, b) => b.weight - a.weight).slice(0, 3).map(x => `- ${x.text}`).join('\n') || '- Nothing notable';
const pct = (now, before) => (before ? Math.round((100 * (now - before)) / before) : null);

return Object.values(advisors).map(adv => {
  const wins = [];
  const risks = [];
  for (const s of adv.rows) {
    if (s.chapters_ready) wins.push({ weight: 10 * s.chapters_ready, text: `${s.student_name}: ${s.chapters_ready} chapter(s) reached exam-ready` });
    if (s.milestones_done) wins.push({ weight: 8 * s.milestones_done, text: `${s.student_name}: ${s.milestones_done} roadmap milestone(s) done` });
    const focusDelta = pct(s.focus_min, s.prev_focus_min);
    if (focusDelta >= 20) wins.push({ weight: focusDelta / 5, text: `${s.student_name}: focus time up ${focusDelta}% week on week` });
    if (s.quiz_pct != null && s.prev_quiz_pct != null && s.quiz_pct - s.prev_quiz_pct >= 5) wins.push({ weight: s.quiz_pct - s.prev_quiz_pct, text: `${s.student_name}: quiz avg up to ${s.quiz_pct}%` });
    if (s.open_alerts) risks.push({ weight: 10 * s.open_alerts, text: `${s.student_name}: ${s.alert_details}` });
    if (focusDelta != null && focusDelta <= -20) risks.push({ weight: -focusDelta / 5, text: `${s.student_name}: focus time down ${-focusDelta}% week on week` });
    if (s.app_days < 4) risks.push({ weight: 7 - s.app_days, text: `${s.student_name}: opened the app on ${s.app_days}/7 days` });
  }
  const table = adv.rows
    .map(s => `| ${s.student_name} | ${s.attention_score} | ${s.focus_min} | ${s.quiz_pct ?? '-'} | ${s.timetable_pct ?? '-'} | ${s.app_days}/7 | ${s.sleep_h ?? '-'} |`)
    .join('\n');
  const content = [
    `## ${adv.name}: week of ${weekOf}`,
    '',
    '### Students by needs-attention',
    '| Student | Attention | Focus min | Quiz % | Timetable % | App days | Sleep h |',
    '|---|---|---|---|---|---|---|',
    table,
    '',
    '### Top 3 wins',
    top3(wins),
    '',
    '### Top 3 risks',
    top3(risks),
  ].join('\n');
  return { json: { advisor_name: adv.name, clickup_user_id: adv.clickup_user_id, title: `Monday review: ${adv.name} (week of ${weekOf})`, content } };
});
